command:
mkcd() { mkdir -p "$1" && cd "$1"; }
# mkcd project
# (now in ./project)

head -n 5 /etc/*.conf
/etc/ssh/sshd_config:
# Package generated configuration file
# See the sshd_config(5) manpage for details.
Port 22
#ListenAddress 0.0.0.0
/etc/nginx/nginx.conf:
user  nginx;
worker_processes  auto;
error_log  /var/log/nginx/error.log warn;
pid        /var/run/nginx.pid;

read -r ans
case "$ans" in
  [yY]) echo "Yes" ;;
  [nN]) echo "No" ;;
  *) echo "Invalid" ;;
esac

list_procs() {
  ps -eo pid,pcpu,pmem,comm --no-headers | grep -i "$1" | sort -k2 -nr | awk '{printf "%6s %5s %5s %s\n", $1, $2"%", $3"%", $4}'
}
# Usage: list_procs nginx

#!/usr/bin/env bash
success=0; fail=0;
jq -r '.url' | xargs -P3 -I{} bash -c 'if curl -s -O "{}"; then echo "OK {}"; exit 0; else echo "FAIL {}"; exit 1; fi' | while read -r status url; do if [[ $status == OK* ]]; then ((success++)); else ((fail++)); fi; done

echo "Downloaded: $success, Failed: $fail"

function archive_oldest() {
  local dir="$1" ext="$2" n=$3
  mkdir -p "$dir/archive"
  ls -1t "$dir"/*.${ext} | tail -n +$((n+1)) | xargs -I{} mv "{}" "$dir/archive/"
}
# Usage: archive_oldest /var/log txt 10

#!/usr/bin/env bash
max=10
sem(){
  while (( $(jobs -r | wc -l) >= max )); do sleep 0.1; done
  "$@" &
}
while read -r host; do
  sem ping -c1 -W2 "$host" > /dev/null && echo "$host" >> reachable.txt || echo "$host" >> unreachable.txt
done < hosts.txt
wait

function safe_rebase_push() {
  local branch="$1"
  local cur_branch=$(git rev-parse --abbrev-ref HEAD)
  git checkout "$branch" && git rebase master && \
    if ./run_tests.sh; then git push origin "$branch"; else git rebase --abort; git checkout "$cur_branch"; fi
}

backup_mysql(){
  local db=$1; local user=$2; local host=$3; local dest=$4;
  local start=$(date +%s);
  mysqldump -u "$user" "$db" | gzip | ssh "$host" "cat > \"$dest/$(date +%F_%T)_${db}.sql.gz\"";
  local end=$(date +%s);
  echo "Backup of $db completed in $((end-start)) seconds" >> ~/backup.log;
}

tail -F /var/log/syslog | awk '/CRITICAL/ {print $1" "$2" "$3" "$0}' | while read ts1 ts2 ts3 line; do
  ts="${ts1} ${ts2} ${ts3}";
  key=$(echo "$line" | md5sum | cut -d' ' -f1);
  if ! test -f "/tmp/alert_${key}.lock"; then
    curl -s -X POST -H 'Content-Type: application/json' -d "{\"timestamp\":\"$ts\",\"message\":\"$(echo $line | sed 's/"/\\"/g')\"}" https://example.com/webhook;
    touch "/tmp/alert_${key}.lock";
    (sleep 300; rm -f "/tmp/alert_${key}.lock") &
  fi;
 done

find . -type f -name '*.conf' -exec grep -Iq . {} \; -and -exec grep -q 'enabled' {} \; -print0 | while IFS= read -r -d '' file; do
  perms=$(stat -c %a "$file");
  ts=$(stat -c %y "$file");
  sed -i 's/foo/bar/g' "$file";
  chmod "$perms" "$file";
  touch -d "$ts" "$file";
done

find /usr/local -xtype l -print0 | while IFS= read -r -d '' link; do
  echo "Deleting broken link: $link" >> /var/log/broken_links.log;
  rm "$link";
 done

size_recent(){
  local dir=$1;
  find "$dir" -type f -mtime -1 -print0 | du --files0-from=- -ch | tail -1 | awk '{print $1}';
}

docker ps -a --filter 'status=exited' --format '{{.ID}} {{.RunningFor}} {{.ExitCode}}' | while read id when code; do
  if [[ $code -ne 0 && $(date -d "$when" +%s) -ge $(date -d '24 hours ago' +%s) ]]; then
    echo "$(date): Removing container $id with exit code $code" >> /var/log/docker_cleanup.log;
    docker rm $id;
  fi;
done

git_rebase_and_push(){
  local branch=$1; local cur=$(git rev-parse --abbrev-ref HEAD);
  git checkout "$branch" && git rebase main && make test && git push && git checkout "$cur" || { git rebase --abort; git checkout "$cur"; echo "Rebase failed or tests failed"; };
}

#!/usr/bin/env bash
while read user; do
  if ! id -u "$user" >/dev/null 2>&1; then
    pass=$(openssl rand -base64 12);
    useradd -m "$user" && echo "$user:$pass" | chpasswd;
    echo "$user,$pass" >> created_users.csv;
  fi;
done < users.txt

#!/usr/bin/env bash
sem(){
  while (( $(jobs -r | wc -l) >= $1 )); do sleep 0.1; done
}
while read -r host; do
  sem 5
  (
    if ping -c1 -W2 "$host" &>/dev/null; then echo "$host" >> up.txt; else echo "$host" >> down.txt; fi
  ) &
done < hosts.txt
wait

monitor_cpu(){
  end=$((SECONDS+60))
  while [ $SECONDS -lt $end ]; do
    cpu=$(awk '/^cpu /{usage=($2+$4)*100/($2+$3+$4+$5+$6+$7+$8)} END{print usage}' /proc/stat)
    echo "$(date +%T) CPU: $cpu%" >> /tmp/cpu.log
    sleep 5
  done
}
monitor_cpu

tree_depth(){
  local dir=$1
  find "$dir" -mindepth 1 -maxdepth 3 -type d ! -path "*/.*" -printf "%p
" | sed -e 's|[^/]*/|│   |g' -e 's|│   \([^│]*\)$|├── \1|' -e 's|│   $|└── |'
}
# Usage: tree_depth /path/to/dir

rotate_logs(){
  dir=$1; max=$2;
  ls -1t "$dir"/*.log 2>/dev/null | tail -n +$((max+1)) | while read old; do
    rm -f "$old" && echo "Deleted $old";
  done
}
# Example: rotate_logs /var/log/myapp 7

#!/usr/bin/env bash
largest_files(){
  local dir="${1:-.}"
  find "$dir" -type f -printf "%s %p\n" |\
    sort -rn |\
    head -n 5 |\
    awk '{printf "%s\t%s\n", $1/1024/1024 "MiB", $2}'
}
# Usage: largest_files /path/to/dir

#!/usr/bin/env bash
awk '$9 ~ /^5/ {print $1}' /var/log/apache2/access.log |\
  sort | uniq -c | sort -rn | head -n 10

#!/usr/bin/env bash
git_test_at(){
  local commit="$1"
  local current_branch=$(git rev-parse --abbrev-ref HEAD)
  git checkout --detach "$commit" && \
    make test; local status=$?
  git checkout "$current_branch"
  return $status
}
# Usage: git_test_at <commit-hash>

#!/usr/bin/env bash
awk -F',' 'NR==1{for(i=1;i<=NF;i++)h[i]=$i;next}{printf "{"; for(i=1;i<=NF;i++){printf "\"%s\": \"%s\"", h[i], $i; if(i<NF)printf ", "} printf "},\n"}' input.csv |\
  sed '$ s/,$//' > output.json

#!/usr/bin/env bash
journalctl -p err..alert --since "1 hour ago" -o json |\
  jq -r '.MESSAGE' | sort -u > err_messages.txt

rotate_logs() {
  local dir="$1"
  find "$dir" -type f -name "*.log" -mtime +14 -exec gzip -9 {} \; -exec rm -f {} \;
  find "$dir" -type f -name "*.log.gz" -size +100M -delete
}
# Usage: rotate_logs /var/log

dir_tree() {
  local base="$1"
  find "$base" -mindepth 1 -maxdepth 3 -type d -exec du -sm {} + | sort -hr
}

git_rebase_and_push() {
  local branch=$1 prev=$(git rev-parse --abbrev-ref HEAD)
  git checkout "$branch" && git fetch origin && git rebase origin/main && make test && git push origin "$branch" || { git rebase --abort; git checkout "$prev"; }
}

largest_files() {
  local dir="${1:-.}" ext="${2:-*}" n="${3:-5}"
  find "$dir" -type f -name "*.$ext" -printf "%s %p\n" | sort -rn | head -n "$n"
}
# Example: largest_files /var/log log 10

#!/usr/bin/env bash
find_symlinks_outside(){
  local base=$(realpath "$1")
  find "$base" -type l -printf "%p %l\n" | while read -r link target; do
    t=$(realpath -m "$target")
    case "$t" in $base/*) ;; *) printf "%s -> %s\n" "$link" "$t" ;; esac
  done
}
# Usage: find_symlinks_outside /opt/app

#!/usr/bin/env bash
find /srv \( -type f -o -type d \) ! -user root -exec chgrp admin {} +
find /srv -type d -exec chmod 2775 {} +

#!/usr/bin/env bash
size_histogram(){
  local dir=$1
  find "$dir" -type f -printf "%s\n" | awk '{
    if($1<1024) r="0-1KB";
    else if($1<10240) r="1KB-10KB";
    else if($1<102400) r="10KB-100KB";
    else if($1<1048576) r="100KB-1MB";
    else r=">1MB";
    count[r]++
  } END{for(r in count) printf "%s: %d\n", r, count[r]}'
}
# Usage: size_histogram /var/log

#!/usr/bin/env bash
max_jobs=10
sem(){
  while [ $(jobs -rp | wc -l) -ge $max_jobs ]; do sleep 0.1; done
  "$@" &
}
while read -r host; do
  sem bash -c "if ping -c1 -W1 \"$host\" &>/dev/null; then echo \"$host\" >> reachable.txt; else echo \"$host\" >> unreachable.txt; fi"
done < hosts.txt
wait

commit_stats() {
  local commit="$1"
  git show --stat --oneline "$commit" | tail -n +2 | awk '{print $1, $2, $3}'
}
# Example: commit_stats a1b2c3d

#!/usr/bin/env bash
cleanup_tmp(){
    local log="/var/log/cleanup.log"
    find /tmp -type f -mtime +7 ! -name "*.keep" -print0 |
        while IFS= read -r -d '' file; do
            rm -f "$file" && echo "$(date +'%F %T') Deleted $file" >> "$log"
        done
}
# Call cleanup_tmp

#!/usr/bin/env bash
grep "Failed password" /var/log/auth.log |
    awk -F' ' '{for(i=1;i<=NF;i++) if($i=="for") user=$(i+1); if($i=="from") ip=$(i+1); print user"@"ip}'

#!/usr/bin/env bash
generate_manifest(){
    local dir="$1"
    (cd "$dir" && find . -type f -exec sha256sum {} +) > "$dir/checksums.sha256"
}
# Example: generate_manifest /opt/data

#!/usr/bin/env bash
journalctl -p err --since "1 hour ago" -o json |
    jq -c '{pid: ._PID, message: .MESSAGE}' | jq -s '.'

#!/usr/bin/env bash
backup_mysql(){
    local recipient="$1"
    local ts=$(date +%Y%m%d%H%M%S)
    local dump="/backups/mysql/all_$ts.sql"
    mysqldump --all-databases | gzip > "$dump.gz"
    gpg --encrypt --recipient "$recipient" "$dump.gz"
    rm -f "$dump.gz"
}
# Example: backup_mysql "admin@example.com"

#!/usr/bin/env bash
WEBHOOK='https://hooks.slack.com/services/XXX/YYY/ZZZ'
while sleep 60; do sec=$(mysql -N -e "SHOW SLAVE STATUS\G" | awk '/Seconds_Behind_Master/ {print $2}'); if [ "$sec" -gt 30 ]; then curl -X POST -H 'Content-type: application/json' --data "{\"text\": \"Replication lag: $sec seconds\"}" "$WEBHOOK"; fi; done

json_key_count() {
  local file=$1
  local key=$2
  jq "..|objects|.\"$key\"?" "$file" | grep -c .
}

awk 'NR>1 {print $4}' /proc/net/tcp | while read -r state; do
  case $state in
    01) echo ESTABLISHED;;
    0A) echo LISTEN;;
    02) echo SYN_SENT;;
    03) echo SYN_RECV;;
    04) echo FIN_WAIT1;;
    05) echo FIN_WAIT2;;
    06) echo TIME_WAIT;;
    07) echo CLOSE;;
    08) echo CLOSE_WAIT;;
    09) echo LAST_ACK;;
    0B) echo CLOSING;;
    *) echo UNKNOWN;;
  esac
done | sort | uniq -c | sort -nr

largest_files(){
  dir=${1:-.}
  find "$dir" -type f -printf "%s %p\n" | sort -nr | head -5 | numfmt --field=1 --to=iec-i --suffix=B --padding=7
}
# Usage: largest_files /var/log

tar_recent(){
  dir=${1:-.}
  days=${2:-7}
  tar -czf recent_$(date +%Y%m%d).tar.gz -C "$dir" \
    $(find "$dir" -type f -mtime -$days -printf "%P ")
}
# Usage: tar_recent /var/www 3

#!/usr/bin/env bash
report=$(du -sh /home/* | sort -hr)
echo -e "Disk usage per user:\n$report" | mail -s "Home Disk Usage Report" root

#!/usr/bin/env bash
log=/var/log/pg_backup.log
pg_dumpall | gzip | aws s3 cp - s3://my-backups/pg_backup_$(date +%F_%H-%M-%S).sql.gz >> "$log" 2>&1

rotate_logs(){
  local dir="$1"
  find "$dir" -type f -name '*.log' -mtime +7 -exec gzip {} \; 
  find "$dir" -type f -name '*.gz' -mtime +30 -delete
}

tmpfifo=$(mktemp -u); mkfifo "$tmpfifo" && {
  while :; do date; sleep 1; done > "$tmpfifo" &
  head -n 5 < "$tmpfifo"
  kill $! 2>/dev/null
  rm -f "$tmpfifo"
}

total_lines(){
  dir="$1"
  pat="$2"
  find "$dir" -type f -name "$pat" -exec wc -l {} + | awk 'END{print $1}'
}

#!/usr/bin/env bash
archive_recent() {
  dir="$1"
  archive="$(basename "$dir")_$(date +%Y%m%d).tar.gz"
  find "$dir" -type f -mtime -7 -print0 |
    tar --null -czvf "$archive" --no-recursion -T -
  du -h "$archive"
}
# Usage: archive_recent /path/to/dir

csvfile="data.csv"
awk -F, -v today=$(date +%s) 'NR>1 {
  cmd="date -d "$1" +%s"; cmd|getline ts; close(cmd);
  if (today - ts <= 30*24*3600) sum+=$2
} END {print sum}' "$csvfile"

#!/usr/bin/env bash
make_manifest() {
  dir="$1"
  manifest="$dir/manifest.sha256"
  find "$dir" -type f -exec sha256sum {} + > "$manifest"
}
verify_manifest() {
  manifest="$1"
  cd "$(dirname "$manifest")"
  sha256sum -c "$(basename "$manifest")" 2>&1 | grep -v "OK$" || echo "All files verified."
}
# Usage: make_manifest /path/to/dir && verify_manifest /path/to/dir/manifest.sha256

#!/usr/bin/env bash
replace_todo() {
  dir="$1"
  find "$dir" -type f -name "*.md" -mtime -2 -exec sed -i 's/TODO/DONE/g' {} +
}
# Usage: replace_todo /path/to/docs
